head.script:
scwin.equalWidth = function() {
    let colum_width = WebSquare.wUnit.getDomById('wq_uuid_5_column7').offsetWidth * 2;
	let filterList_Width = WebSquare.wUnit.getDomById('wq_uuid_5_customFilter_scrollView').offsetWidth;
	console.log("colum_width : " + colum_width);
	console.log("filterList_Width : " + filterList_Width);	
    if (colum_width < filterList_Width) {
        return true;
    }
    return false;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Source 탭 -> useFilterList="true" 인지 확인한다.
    //Make sure the Source tab -> useFilterList = "true".
    //Verify 1. useFilterList="true"
    //Test step 2. 브라우저에서 FilterList 목록을 선택한다.
    //In the browser, select the FilterList list.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_5_column7_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 선택한 FilterList 리스트가 잘림현상 없이 정상적으로 펼쳐진다.
    //The selected FilterList list is truncated It unfolds normally.
    WebSquare.wUnit.addCommand("assert", "scwin.equalWidth()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

